() => new Promise((resolve) => { const s = window.__oprnHooksScene; const c = s.cameras.main;
  document.querySelectorAll('.zone-feedback,[data-testid=objective-card],.touch-pad,.play-fullscreen-toggle').forEach(e => e.style.display='none');
  if (s.player) s.player.setVisible(false);
  for (const [k,v] of s.eventSprites) { if (/walker|crowd|commuter|extra|rusher|ev_fl_y_/.test(k)) v.setVisible(false); }
  c.stopFollow(); c.removeBounds && c.removeBounds();
  const W = s.map.width*16, H = s.map.height*16, vw = c.width / c.zoom, vh = c.height / c.zoom;
  const spots = []; for (let y = 0; y < H; y += vh) for (let x = 0; x < W; x += vw) spots.push([Math.min(x, Math.max(0, W - vw)), Math.min(y, Math.max(0, H - vh))]);
  const out = []; let i = 0;
  const next = () => { if (i >= spots.length) { resolve({ zoom: c.zoom, vw, vh, W, H, shots: out }); return; }
    const [x, y] = spots[i++]; c.setScroll(x, y); let n = 0;
    const tick = () => { if (++n < 5) { requestAnimationFrame(tick); return; }
      s.game.renderer.snapshot((img) => { out.push({ sx: c.scrollX, sy: c.scrollY, src: img.src }); next(); }); };
    requestAnimationFrame(tick); };
  next(); })

